package store.cadera.cdrjobs.listener;
import net.kyori.adventure.text.Component;import org.bukkit.*;import org.bukkit.block.Block;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.EntityExplodeEvent;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.api.*;import store.cadera.cdrjobs.api.event.ProfessionActionEvent;import store.cadera.cdrjobs.data.ProfessionStore;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;import java.util.*;
public final class LumberjackListener implements Listener{private static final Set<Material>ELDER=EnumSet.of(Material.DARK_OAK_LOG,Material.MANGROVE_LOG,Material.CHERRY_LOG);private final CdrJobsPlugin plugin;private final ProfessionStore store;private final ProgressionService progression;private final LumberjackService lumber;private final LevelService levels;private Map<Material,Integer>xp=new HashMap<>();public LumberjackListener(CdrJobsPlugin p,ProfessionStore s,ProgressionService pr,LumberjackService w,LevelService l){plugin=p;store=s;progression=pr;lumber=w;levels=l;refreshXpMap();}public void refreshXpMap(){xp=plugin.loadActivityXp("lumberjack.xp");}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void place(BlockPlaceEvent e){if(plugin.getConfig().getBoolean("lumberjack.enabled",true)&&xp.containsKey(e.getBlockPlaced().getType()))store.markPlacedJobBlock(e.getBlockPlaced().getLocation(),LumberjackService.JOB);}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void cut(BlockBreakEvent e){if(!plugin.getConfig().getBoolean("lumberjack.enabled",true))return;Integer base=xp.get(e.getBlock().getType());if(base==null||store.consumePlacedJobBlock(e.getBlock().getLocation(),LumberjackService.JOB))return;Player p=e.getPlayer();lumber.recordChop(p,ELDER.contains(e.getBlock().getType()));plugin.getServer().getPluginManager().callEvent(new ProfessionActionEvent(p,JobType.LUMBERJACK,ProfessionActionType.CHOP_LOG,1));long amount=lumber.applyXp(p,Math.max(1,Math.round(base*Math.max(0,plugin.getConfig().getDouble("lumberjack.xp-multiplier",1)))));JobProgress pr=progression.addXp(p,JobType.LUMBERJACK,amount);if(plugin.getConfig().getBoolean("settings.actionbar-xp",true)){long req=levels.xpRequiredForNextLevel(pr.level());p.sendActionBar(Component.text(pr.level()>=levels.maxLevel()?"✦ Ironbark Warden Lv."+levels.maxLevel()+" • MAX":"✦ Ironbark +"+amount+" XP • Lv."+pr.level()+" • "+pr.xp()+"/"+req));}}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void ex(BlockPistonExtendEvent e){move(e.getBlocks(),e.getDirection());}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void ret(BlockPistonRetractEvent e){move(e.getBlocks(),e.getDirection().getOppositeFace());}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void be(BlockExplodeEvent e){clean(e.blockList());}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void ee(EntityExplodeEvent e){clean(e.blockList());}private void move(List<Block>bs,org.bukkit.block.BlockFace d){if(!plugin.getConfig().getBoolean("lumberjack.anti-exploit.piston-tracking",true))return;List<Location>tos=new ArrayList<>();for(Block b:bs)if(xp.containsKey(b.getType())&&store.consumePlacedJobBlock(b.getLocation(),LumberjackService.JOB))tos.add(b.getRelative(d).getLocation());tos.forEach(l->store.markPlacedJobBlock(l,LumberjackService.JOB));}private void clean(List<Block>bs){for(Block b:bs)if(xp.containsKey(b.getType()))store.consumePlacedJobBlock(b.getLocation(),LumberjackService.JOB);}
}
